package ir.sejadalmas.salesagent;
import android.app.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;
public class MainActivity extends Activity{
 final int NAVY=Color.rgb(20,36,52),GOLD=Color.rgb(220,143,0),BG=Color.rgb(246,247,249),MUTED=Color.rgb(111,120,130),LINE=Color.rgb(230,233,237);LinearLayout content;String base="https://sejadalmas.iq",token="";
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);token=getPreferences(0).getString("token","");splash();}
 int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int fill,int stroke,int r){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(r));if(stroke!=Color.TRANSPARENT)d.setStroke(dp(1),stroke);return d;}
 TextView tx(String s,int sp,int c,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(c);v.setGravity(Gravity.RIGHT);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;}
 void splash(){FrameLayout f=new FrameLayout(this);f.setBackgroundColor(Color.WHITE);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(34),0,dp(34),0);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.almas_logo);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);box.addView(logo,new LinearLayout.LayoutParams(-1,dp(78)));TextView cap=tx("همراه هوشمند فروش الماس",13,MUTED,false);cap.setGravity(Gravity.CENTER);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.topMargin=dp(22);box.addView(cap,cp);ProgressBar p=new ProgressBar(this);LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(dp(26),dp(26));pp.gravity=Gravity.CENTER;pp.topMargin=dp(26);box.addView(p,pp);f.addView(box,new FrameLayout.LayoutParams(-1,-1));setContentView(f);new Handler(Looper.getMainLooper()).postDelayed(()->{if(token.isEmpty())login();else home();},950);}
 void frame(){FrameLayout page=new FrameLayout(this);page.setBackgroundColor(BG);View halo=new View(this);GradientDrawable hg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(255,248,234),Color.rgb(246,247,249)});hg.setShape(GradientDrawable.OVAL);halo.setBackground(hg);FrameLayout.LayoutParams hp=new FrameLayout.LayoutParams(dp(330),dp(330));hp.gravity=Gravity.TOP|Gravity.RIGHT;hp.topMargin=-dp(150);hp.rightMargin=-dp(130);page.addView(halo,hp);ScrollView sv=new ScrollView(this);sv.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);content.setPadding(dp(24),dp(18),dp(24),dp(28));sv.addView(content,new ScrollView.LayoutParams(-1,-1));page.addView(sv,new FrameLayout.LayoutParams(-1,-1));setContentView(page);}
 EditText field(String hint){EditText e=new EditText(this);e.setHint(hint);e.setHintTextColor(Color.rgb(170,176,183));e.setTextColor(NAVY);e.setTextSize(15);e.setSingleLine();e.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);e.setPadding(dp(18),0,dp(18),0);e.setBackground(shape(Color.WHITE,LINE,18));e.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(56)));return e;} void gap(int h){content.addView(new Space(this),new LinearLayout.LayoutParams(1,dp(h)));}
 Button primary(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(Color.WHITE);b.setTextSize(15);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(shape(NAVY,Color.TRANSPARENT,18));b.setElevation(dp(3));b.setLayoutParams(new LinearLayout.LayoutParams(-1,dp(58)));return b;}
 void login(){frame();gap(30);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.almas_logo);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(62));lp.gravity=Gravity.CENTER;content.addView(logo,lp);gap(30);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);card.setPadding(dp(20),dp(24),dp(20),dp(22));card.setBackground(shape(Color.WHITE,Color.rgb(236,238,241),24));card.setElevation(dp(2));content.addView(card,new LinearLayout.LayoutParams(-1,-2));TextView title=tx("خوش آمدید",24,NAVY,true);title.setGravity(Gravity.RIGHT);card.addView(title);TextView sub=tx("با حساب کاربری فروش خود وارد شوید",13,MUTED,false);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,-2);sp.topMargin=dp(6);sp.bottomMargin=dp(22);card.addView(sub,sp);TextView el=tx("ایمیل کارشناس",12,NAVY,true);card.addView(el);EditText email=field("name@sejadalmas.iq");LinearLayout.LayoutParams ep=new LinearLayout.LayoutParams(-1,dp(56));ep.topMargin=dp(7);ep.bottomMargin=dp(16);card.addView(email,ep);TextView pl=tx("رمز عبور",12,NAVY,true);card.addView(pl);EditText pass=field("رمز عبور");pass.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);LinearLayout.LayoutParams psp=new LinearLayout.LayoutParams(-1,dp(56));psp.topMargin=dp(7);psp.bottomMargin=dp(20);card.addView(pass,psp);Button enter=primary("ورود به سامانه");card.addView(enter);ProgressBar busy=new ProgressBar(this);busy.setVisibility(View.GONE);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(26),dp(26));bp.gravity=Gravity.CENTER;bp.topMargin=dp(14);card.addView(busy,bp);TextView msg=tx("",12,Color.rgb(183,57,57),false);msg.setGravity(Gravity.CENTER);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,-2);mp.topMargin=dp(10);card.addView(msg,mp);gap(22);TextView foot=tx("اپلیکیشن کارشناسان فروش • الماس کاشان",11,MUTED,false);foot.setGravity(Gravity.CENTER);content.addView(foot);
 enter.setOnClickListener(v->{String em=email.getText().toString().trim(),pw=pass.getText().toString();if(em.isEmpty()||pw.isEmpty()){msg.setText("ایمیل و رمز عبور را وارد کنید.");return;}enter.setEnabled(false);enter.setText("در حال بررسی…");busy.setVisibility(View.VISIBLE);msg.setText("");new Thread(()->{try{Api api=new Api(base,"");JSONObject h=api.health();if(!h.optBoolean("success"))throw new Exception("سرویس موبایل آماده نیست.");JSONObject d=new JSONObject().put("email",em).put("password",pw).put("device","Android Sales Agent 0.1.3");JSONObject r=api.call("login","POST",d);runOnUiThread(()->{if(r.optBoolean("success")){token=r.optString("token");getPreferences(0).edit().putString("token",token).apply();home();}else reset(enter,busy,msg,r.optString("message","ورود انجام نشد."));});}catch(Exception e){runOnUiThread(()->reset(enter,busy,msg,e.getMessage()));}}).start();});}
 void reset(Button b,ProgressBar p,TextView m,String s){b.setEnabled(true);b.setText("ورود به سامانه");p.setVisibility(View.GONE);m.setText(s);}
 void home(){frame();gap(35);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.almas_logo);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);content.addView(logo,new LinearLayout.LayoutParams(-1,dp(58)));gap(28);content.addView(tx("میز کار فروش",26,NAVY,true));gap(8);content.addView(tx("اتصال امن برقرار است. داشبورد فروش در مرحله بعد روی همین نسخه تکمیل می‌شود.",14,MUTED,false));gap(26);Button out=primary("خروج از حساب");content.addView(out);out.setOnClickListener(v->{getPreferences(0).edit().clear().apply();token="";login();});}
}
